def find_by_artist(playlist, artist):
    """Returns a list of song titles by the given artist."""
    return [song['title'] for song in playlist if song['artist'] == artist]

def sort_by_duration(playlist):
    """Returns the playlist sorted from shortest to longest song."""
    playlist_copy = playlist[:]  # Make a copy to avoid changing the original
    n = len(playlist_copy)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if playlist_copy[j]['duration'] < playlist_copy[min_idx]['duration']:
                min_idx = j
        # Swap the found minimum with the first element
        playlist_copy[i], playlist_copy[min_idx] = playlist_copy[min_idx], playlist_copy[i]
    return playlist_copy

def build_playlist(songs, max_duration):
    total = 0
    result = []
    for song in songs:
        if total + song['duration'] > max_duration:
            break
        result.append(song)
        total += song['duration']
    return result
